Q.budget += 1;
Q.inflation -= 1.5;
Q.unemployed += 1.5;
Q.economic_growth -= 1;
Q.emergency_decree_mitigated = Q.liberal_parliament || (Q.bourgeois_parliament && !Q.lvp_formed) || Q.lvp_formed;
if (Q.emergency_decree_mitigated) {
    Q.unemployed -= 0.5;
    Q.budget -= 1;
    Q.inflation += 0.8;
    Q.economic_growth += 0.4;
    Q.new_middle_ddp += 2;
    Q.old_middle_ddp += 1;
    Q.new_middle_dvp += 3;
    Q.old_middle_dvp += 3;
    Q.rural_dvp += 1;
    Q.new_middle_lvp += 4;
    Q.old_middle_lvp += 6;
    Q.rural_lvp += 2;
    Q.new_middle_nsdap -= 4;
    Q.old_middle_nsdap -= 4;
    Q.dvp_left += 3;
    Q.ddp_left += 2;
    Q.ddp_cohesion += 2;
    Q.lvp_left += 3;
}
