        Q.flavour_61_trigger_shown = 1;
    }
}
if (Q.kpd_wholesome) {
    Q.flavour_62_trigger += 1;
    if (Q.flavour_62_trigger && !Q.flavour_62_trigger_shown) {
        Q.flavour_62_trigger_time = Q.time;
        if (Q.rubicon) Q.flavour_62_trigger_time = Q.rubicon_time;
        Q.flavour_62_trigger_shown = 1;
    }
}
const boxes = document.querySelectorAll('.scrollable-box');
if (boxes.length >= 2) {
    boxes[1].remove();
}
Q.last_time_updated = Q.time;
if (Q.week) Q.last_week_updated = Q.week;

