if (Q.ddp_leader == "Dietrich") saxony_adjustment_factors.ddp -= 0.1;
if (!Q.dvp_exist) saxony_adjustment_factors.ddp += 0.2;
Q.ddp_saxony_elections_vote = Q.ddp_votes*saxony_adjustment_factors.ddp;
if (Q.lvp_leader == "Dieckmann") saxony_adjustment_factors.lvp += 0.1;
if (Q.lvp_leader == "Glatzel") saxony_adjustment_factors.lvp += 0.1;
Q.lvp_saxony_elections_vote = Q.lvp_votes*saxony_adjustment_factors.lvp;
if (Q.stegerwald_path) saxony_adjustment_factors.z += 1.0;
if (Q.cvp_formed && Q.cvp_leader == "Stegerwald") saxony_adjustment_factors.z += 0.1;
if (Q.cvp_formed && Q.cvp_leader == "Lambach") saxony_adjustment_factors.z += 0.1;
